		}
		else {
			def.setValue(settings, value);
		}
	}

	private string[] addNoChoice(string[] choices) {
		string[] newChoices = new string[choices.length + 1];
		newChoices[0] = NO_CHOICE;
		Array.Copy(choices, 0, newChoices, 1, choices.length);
		return newChoices;
	}

